sys_script_include.script:
var TaskUtilsClient = Class.create();
TaskUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getTasksByEvent: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(
                gr.getValue('number') + ' | ' +
                gr.getValue('u_task_name') + ' | ' +
                gr.getDisplayValue('u_due_date')
            );
        }
        return result.length ? result.join('\n') : 'No tasks found for this event';
    },

    isTaskOverdue: function() {
        var taskId = this.getParameter('sysparm_task_id');
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('number', taskId);
        gr.query();
        while (gr.next()) {
            var dueDate = new GlideDateTime(gr.getValue('u_due_date'));
            var now = new GlideDateTime();
            if (dueDate.before(now)) {
                return 'task is overdue';
            }
        }
        return 'task is not overdue';
    },

    getTaskDetailsById: function() {
        var taskId = this.getParameter('sysparm_task_id');
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('number', taskId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(
                'Name: ' + gr.getValue('u_task_name') +
                ', Assigned To: ' + gr.getDisplayValue('u_assigned_to') +
                ', Due Date: ' + gr.getDisplayValue('u_due_date') +
                ', Status: ' + gr.getValue('u_status')
            );
        }
        return result.length ? result.join('\n') : 'Task not found';
    },

    getTasksByDueDate: function() {
        var dueDate = this.getParameter('sysparm_due_date'); // format: yyyy-MM-dd
        var gr = new GlideRecord('x_1790116_event_ma_task');
        gr.addQuery('u_due_date', dueDate);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(
                gr.getValue('number') + ' | ' + gr.getValue('u_task_name')
            );
        }
        return result.length ? result.join('\n') : 'No tasks found on this due date';
    },
	cancelTask: function() {
        var taskId = this.getParameter('sysparm_taskId');

        var gr = new GlideRecord('x_1790116_event_ma_task');
        if (gr.get(taskId)) {
            gr.u_choice_4 = 'cancelled';
            gr.update();

            gs.eventQueue('x_1790116_event_ma.event.cancel.notify', gr, gr.assigned_to, gr.sys_id);
            return 'success';
        }
        return 'failure';
    },

    type: 'TaskUtilsClient'
});
